ROOT=Path(__file__).resolve().parents[1]
def md(x):return nbf.v4.new_markdown_cell(x)
def code(x):return nbf.v4.new_code_cell(x)
setup="""from pathlib import Path
import sys, json, yaml, numpy as np, pandas as pd
from IPython.display import display, Image
ROOT = Path.cwd().parent if Path.cwd().name == 'notebooks' else Path.cwd()
sys.path.insert(0, str(ROOT / 'src'))
from momentum_hw2.data_validation import load
from momentum_hw2.metrics import monthly, summary
cfg = yaml.safe_load((ROOT / 'config/base.yaml').read_text())
a, prices, rf, raw = load(cfg)
pd.options.display.float_format = '{:.5f}'.format
display(json.loads((ROOT / 'research/freeze.json').read_text()))
"""
factor=[md('# Prototype A: crash-aware equity momentum factor\n\nHanyu Zhang | FINCB9339 Homework 2. This executed notebook explains the tested modules. It is an aggregate factor exposure experiment using a stylized funded capital convention, not a stock portfolio. Primary cash-plus-Mom returns are gross. Published findings are motivation, not values reproduced here.'),md('## Inputs and units\nFrench Mom is the average of small/big high prior-return portfolios minus the average of small/big low portfolios; daily portfolios are formed daily. Entries become decimal returns once. Official monthly Mom is a separate monthly construction. Cboe VIX is in points and is joined backward. Current snapshots can revise history; no point-in-time vintage is claimed.'),code(setup+"display(a[['Mom','Mkt-RF','RF','VIX','vix_date','vix_staleness_days']].tail())"),md('## Frozen decisions and timing\nAt the penultimate session close, annual volatility is $\\sqrt{252}$ times sample standard deviation of 126 daily Mom observations. Vol scale is $\\min(1.5,.10/\\max(\\sigma,.05))$. Bear uses negative compounded market **total** return over 24 comparable monthly snapshots. VIX >25 is the second flag. State scale is 1/.5/0 for zero/one/two flags. Execute final close; the prior exposure earns that day, and new exposure earns next session. This fixed heuristic is not Daniel–Moskowitz conditional-mean/variance sizing.'),code("from momentum_hw2.backtest_factor import run_factor\nresults, decisions = run_factor(a, cfg['factor'])\ndisplay(decisions.head(3))\ndisplay(decisions.loc['2009-02-01':'2009-05-31'])"),md('## Reproduce an actual sizing calculation\nRead the endpoints and intermediate volatility. The market index compounds Mkt-RF + RF, not market excess alone.'),code("row = decisions.iloc[0]\ns = row.signal_date\nsigma = a.Mom.loc[:s].tail(126).std(ddof=1) * np.sqrt(252)\nmarket_index = (1 + a['Mkt-RF'] + a.RF).cumprod()\nbear_return = market_index.loc[s] / market_index.loc[row.bear_start] - 1\nassert np.isclose(sigma, row.sigma)\nassert np.isclose(bear_return, row.market_lookback)\ndisplay(pd.Series({'signal':s,'execution':decisions.index[0],'first_return':row.first_return_date,'sigma':sigma,'market_total_24m':bear_return,'vol_scale':row.vol_scale,'regime_scale':row.regime_scale,'combined':row.A3}))"),md('## Capital accounting\n$r_d=f_d+a_{previous}m_d-cost_d$. Mom is already an excess spread; do not subtract RF twice. Conventional unit notional is roughly long $1/short $1, gross 2; cap 1.5 permits gross 3. Earning RF on all collateral, borrow and financing access are assumptions. Zero factor exposure earns cash. At or below -100% modeled return, the pipeline stops rather than reporting a CAGR.'),code("d = results['A3']['daily']\nassert np.allclose((1+d.return_net).cumprod(), d.nav)\nassert np.allclose(d.return_net, d.RF + d.excess_component)\nfor label,z in results.items():\n    saved = pd.read_csv(ROOT/'outputs/tables'/f'{label}_daily.csv',index_col=0,parse_dates=True)\n    assert np.allclose(z['daily'].return_net, saved.return_net, atol=1e-13)\ndisplay(pd.DataFrame({x:summary(z['daily']) for x,z in results.items()}).T[['CAGR','annual_vol','Sharpe','max_daily_drawdown','average_exposure']])"),md('## Actual paths and component attribution\nAll variants use the same dates. Volatility management and states can reduce risk while lowering exposure. These historical outcomes do not guarantee future protection.'),code("display(Image(filename=str(ROOT/'outputs/figures/A_nav_drawdown.png')))\ndisplay(Image(filename=str(ROOT/'outputs/figures/A_exposure_regime.png')))"),md('## Sensitivity, crises and uncertainty\nDefaults remain unchanged. Published WML decile crash numbers are not French Mom estimates. The 2009 rebound and 2020 remain in full-history performance. Long history without VIX is a distinct diagnostic.'),code("display(pd.read_csv(ROOT/'outputs/tables/bootstrap.csv').query(\"prototype=='A'\"))\ndisplay(pd.read_csv(ROOT/'outputs/tables/stress_periods.csv').query(\"variant.str.startswith('A') and period in ['2009_rebound','2020']\",engine='python')[['variant','period','cumulative_return','max_daily_drawdown']])\ndisplay(pd.read_csv(ROOT/'outputs/tables/sensitivities.csv').query(\"prototype=='A'\")[['variant','CAGR','Sharpe','max_daily_drawdown']])"),md('## Limits and sources\nAggregate returns cannot establish sector neutrality, new volatility-adjusted stock selection, constituent turnover, borrow availability or stock capacity. Exposure-change charges and implementation drags omit internal Mom trading. Daily/monthly series stay separate. Course lecture slides 65–88; Daniel & Moskowitz (2016), introduction and section 4; Kolanovic & Wei (2015), pp59–60. Exact local excerpts, provider/issuer URLs and dates are in research/source_map.md. See README for offline commands.')]
etf=[md('# Prototype B: cross-asset ETF dual momentum\n\nHanyu Zhang | FINCB9339 Homework 2. This notebook calls the same tested modules as the project. It uses real Yahoo adjusted returns, French observed cash, drifting weights and modeled costs. The recommended B3 pitch remains research-stage.'),md('## Real history and warmup\nFixed universe: SPY, EFA, EEM, IEF, TLT, GLD, DBC, VNQ. Observed common history starts with DBC; no pre-inception padding. Twelve comparable monthly snapshots create B2 eligibility; B3 additionally requires 126 **strategy** return observations. All primary variants start from cash on B3’s eligible execution. September prices are unused because RF ends in August.'),code(setup+"display(prices.head())\ndisplay(pd.read_csv(ROOT/'outputs/tables/data_coverage.csv'))"),md('## Relative and absolute selection\n$M_i=TR_i(s_t)/TR_i(s_{t-12})-1$. Match cash over exactly the same endpoints. Select top 3 before filtering. A selected slot earns one third if $M_i>C$; otherwise that slot goes to cash. No refill and no survivor renormalization. Alphabetical tie breaks. The primary ETF rule includes the latest month; a skip-month variant is only a sensitivity.'),code("from momentum_hw2.backtest_etf import run_etf\nresults, signals, sizing = run_etf(prices, rf, cfg['etf'])\nexecution = results['B3']['daily'].index[0]\nactual = signals.loc[signals.execution_date == execution]\ndisplay(actual[['ticker','signal_date','execution_date','first_return_date','lookback_start','lookback_end','momentum','cash_hurdle','selected','passes_absolute','B2_target']])"),md('## Independently reconstruct an actual signal and cash hurdle\nAdj Close already incorporates distributions; adding dividends again would double count them.'),code("row = actual.iloc[0]\nstart,end = row.lookback_start,row.lookback_end\nmanual_m = prices.loc[end,row.ticker]/prices.loc[start,row.ticker]-1\nmanual_cash = (1+rf.loc[(rf.index>start)&(rf.index<=end)]).prod()-1\nassert np.isclose(manual_m,row.momentum)\nassert np.isclose(manual_cash,row.cash_hurdle)\ndisplay(pd.Series({'ticker':row.ticker,'momentum_manual':manual_m,'cash_manual':manual_cash,'start':start,'end':end}))"),md('## Volatility cap, not leverage\n$q=\\min(1,.10/\\max(\\widehat\\sigma_{B2},.05))$, using the last 126 gross unscaled B2 daily excess returns at the snapshot. Multiply risky B2 slots by q; route the rest to cash. It never increases low-risk exposure above 100%, and past strategy risk can lag a holdings change.'),code("display(sizing.head())\ndisplay(results['B2']['targets'].loc[execution])\ndisplay(results['B3']['targets'].loc[execution])"),md('## Timing, drift and costs\nPenultimate close decision, final close execution; old positions earn execution-day returns. Between rebalances, weights drift with relative asset growth. Turnover is $T=\\sum_{risky}|target-pretrade|$. A full A-to-B switch is T=2, so 10bps per dollar costs 20bps NAV. Apply NAV haircut then post-cost target allocation; this is the documented proportional-cost approximation. Initial order costs included; monthly investor statistics fold initial execution charge into first full holding month.'),code("d = results['B3']['daily'];h=results['B3']['holdings'];tr=results['B3']['trades']\nassert np.allclose((1+d.return_net).cumprod(),d.nav)\nassert np.allclose(h.sum(axis=1),1) and h.min().min()>=0\nfor label,z in results.items():\n    saved=pd.read_csv(ROOT/'outputs/tables'/f'{label}_daily.csv',index_col=0,parse_dates=True)\n    assert np.allclose(z['daily'].return_net,saved.return_net,atol=1e-13)\ndisplay(tr.loc[tr.execution_date==execution])\ndisplay(pd.DataFrame({x:summary(z['daily']) for x,z in results.items()}).T[['CAGR','annual_vol','Sharpe','max_daily_drawdown','cash_fraction','turnover_annual']])"),md('## Actual results and opportunity costs\nB1 has stronger return than B2/B3 here; B3 reduces drawdown with more cash. 60/40 has higher full-history Sharpe. Do not equate lower exposure with free alpha.'),code("display(Image(filename=str(ROOT/'outputs/figures/B_nav_drawdown.png')))\ndisplay(Image(filename=str(ROOT/'outputs/figures/B_allocations.png')))\ndisplay(Image(filename=str(ROOT/'outputs/figures/B_components.png')))"),md('## Historical validation and paired uncertainty\nDevelopment to 2013, validation 2014–2019, historical holdout from 2020. Preserve earlier signal history. This public historical holdout is inspected, not pristine future evidence. Six-month paired moving-block bootstrap, 1000 draws, seed9339; intervals crossing zero do not establish advantage.'),code("display(pd.read_csv(ROOT/'outputs/tables/performance.csv').query(\"sample=='historical_holdout' and prototype=='B'\")[[ 'variant','CAGR','Sharpe','max_daily_drawdown','average_exposure']])\ndisplay(pd.read_csv(ROOT/'outputs/tables/bootstrap.csv').query(\"prototype=='B' and sample=='full'\"))\ndisplay(pd.read_csv(ROOT/'outputs/tables/sensitivities.csv').query(\"prototype=='B' and component=='B3'\")[[ 'variant','start','CAGR','Sharpe','max_daily_drawdown']])"),md('## Capacity is provisional\nDollar ADV is mean(provider Close times share Volume) over 20 sessions through snapshot, not adjusted price. Participation uses evolving scenario NAV times absolute risky trade weights. No actual auction capacity or spread measurement is claimed. The evolving10m scenario breaches illustrative small-participation constraints in some instruments.'),code("display(pd.read_csv(ROOT/'outputs/tables/capacity_summary.csv').query(\"variant=='B3' and initial_aum==10000000\"))\ndisplay(pd.read_csv(ROOT/'outputs/tables/capacity_trades.csv').query(\"variant=='B3' and ticker=='DBC' and initial_aum==10000000\").nlargest(3,'participation'))"),md('## Research-stage recommendation and sources\nB3 fits a transparent risk-limited ETF design; keep B1 as a serious higher-return comparator and 60/40 as a competitive benchmark. Validate independent prices/actions, consolidated/auction liquidity and prospective time-stamped decisions before any mandate. Preserve holdings and escalate if data/rebalance fails. No trades or submission. Lecture slides22–44; Asness etal2014; Kolanovic–Wei2015 pp19–20,59–60; Baltas–Kosowski supplied2013 section3. Source map and report provide precise references, Q&A, costs and limitations.')]
for name,cells in [('01_factor_overlay.ipynb',factor),('02_etf_dual_momentum.ipynb',etf)]:
    nb=nbf.v4.new_notebook(cells=cells,metadata={'kernelspec':{'display_name':'HW2 Python 3.12','language':'python','name':'hw2'},'language_info':{'name':'python','version':'3.12.7'}})
    nbf.write(nb,ROOT/'notebooks'/name)
k=ROOT/'build/jupyter/kernels/hw2';k.mkdir(parents=True,exist_ok=True)
(k/'kernel.json').write_text(json.dumps({'argv':[str(ROOT/'.venv/bin/python'),'-m','ipykernel_launcher','-f','{connection_file}'],'display_name':'HW2 Python','language':'python'}))
